const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs');
const {request,runRequest}=require('./cutover-maintenance-request.cjs');
const base={GITHUB_REPOSITORY:'videoq-jp/videoq',GITHUB_REF:'refs/heads/main',GITHUB_SHA:'a'.repeat(40),GITHUB_RUN_ID:'123456',OPERATION:'status',CUTOVER_RUN_ID:'b'.repeat(32)};
test('fixed controls map to typed Python arguments',()=>{for(const [operation,kind] of Object.entries({'install-fence':'install-cutover-fence','release-fence':'release-cutover-fence',status:'cutover-status',release:'release-cutover-hold',recover:'recover-cutover-hold','prepare-consumers':'prepare-cutover-consumers','pause-consumers':'pause-cutover-consumers','resume-consumers':'resume-cutover-consumers','retry-consumers':'retry-cutover-consumers','inspect-activity':'inspect-cutover-activity','retry-activity':'retry-cutover-activity'}))assert.deepEqual(request({...base,OPERATION:operation}),{args:[kind,'--run-id',base.CUTOVER_RUN_ID]});});
test('start token remains stable across attempts and changes for another workflow run',()=>{const env={...base,OPERATION:'start',CUTOVER_RUN_ID:''};const a=request({...env,GITHUB_RUN_ATTEMPT:'1'}),b=request({...env,GITHUB_RUN_ATTEMPT:'2'});assert.deepEqual(a,b);assert.match(a.token,/^[a-f0-9]{32}$/);assert.notEqual(a.token,request({...env,GITHUB_RUN_ID:'123457'}).token);});
test('guards reject branch, fork, invalid source, action and run before process execution',()=>{let calls=0;for(const change of [{GITHUB_REF:'refs/heads/feature'},{GITHUB_REPOSITORY:'fork/videoq'},{GITHUB_SHA:'a'},{OPERATION:'__proto__'},{OPERATION:'status; command'},{CUTOVER_RUN_ID:'b'.repeat(32)+'\n'},{CUTOVER_RUN_ID:''},{OPERATION:'start'},{OPERATION:'start',CUTOVER_RUN_ID:'',GITHUB_RUN_ID:'x'}])assert.throws(()=>runRequest({env:{...base,...change},execute:()=>calls++}));assert.equal(calls,0);});
test('child uses execFile and only the derived token overrides inherited token',()=>{const calls=[];runRequest({env:{...base,CUTOVER_HOLD_REQUEST_TOKEN:'untrusted'},execute:(...a)=>calls.push(a)});assert.equal(calls[0][0],'python3');assert.equal(calls[0][2].env.CUTOVER_HOLD_REQUEST_TOKEN,undefined);assert.equal(calls[0][2].stdio,'inherit');runRequest({env:{...base,OPERATION:'start',CUTOVER_RUN_ID:'',CUTOVER_HOLD_REQUEST_TOKEN:'untrusted'},execute:(...a)=>calls.push(a)});assert.equal(calls[1][2].env.CUTOVER_HOLD_REQUEST_TOKEN,request({...base,OPERATION:'start',CUTOVER_RUN_ID:''}).token);});
test('workflow retains main-only protected OIDC boundary and distinct serial control lane',()=>{const s=fs.readFileSync('.github/workflows/d1-cutover-control.yml','utf8');for(const part of ["github.ref == 'refs/heads/main'",'environment: production-db-maintenance','id-token: write','group: production-cutover-control','cancel-in-progress: false','default: status','run: node .github/scripts/cutover-maintenance-request.cjs'])assert.ok(s.includes(part));assert.ok(!/run:.*\$\{\{/.test(s));assert.ok(!s.includes('with-neon-credentials'));});
